package com.osfans.trime.data.theme

import java.io.File
import com.osfans.trime.data.theme.ThemeLog as Timber

/**
 * Edits the `style:` entries of a theme file in place.
 *
 * The document is only touched at the edited line: key order, comments, blank
 * lines and YAML anchors stay exactly as the author wrote them, so a theme
 * keeps working as a portable file instead of being regenerated by a
 * serializer. Only top-level `style:` scalars are handled; nested mappings
 * (`enter_labels`) are left to the file.
 */
object ThemeStyleWriter {
    enum class Source {
        /** Written literally in the theme file. */
        LITERAL,

        /** Written as `*anchor`; the value lives in an anchor definition elsewhere. */
        ANCHOR,

        /** Not present in the file; the runtime uses the model default. */
        ABSENT,
    }

    data class Entry(
        val value: String?,
        val source: Source,
    )

    private const val STYLE_KEY = "style"
    private val ENTRY_INDENT = Regex("""^(\s{2})([A-Za-z0-9_]+):(\s*)(.*)$""")

    /** The source file of [themeId], preferring the user copy over the shared one. */
    fun findSourceFile(themeId: String): File? {
        ThemeDirectory.userFile(themeId)?.takeIf { it.isFile }?.let { return it }
        return ThemeDirectory.sharedFile(themeId)?.takeIf { it.isFile }
    }

    /**
     * The file an editor should both read and write.
     *
     * [findSourceFile] answers "where is this theme"; when the theme dir holds
     * no copy yet it answers `shared/`, and a write there is invisible in the
     * directory the user switched to — that is exactly how keyboard edits used
     * to go missing while style and color edits did not. Every editor takes its
     * file from here so that reading and writing always land on the same copy.
     */
    fun editableSourceFile(themeId: String): File? = ensureEditable(themeId) ?: findSourceFile(themeId)

    fun isUserFile(file: File): Boolean {
        val dir = ThemeDirectory.themeDir ?: return false
        return runCatching { file.canonicalFile.parentFile == dir.canonicalFile }.getOrDefault(false)
    }

    /**
     * Returns a file that can be written: the user copy when it exists, or a copy
     * of the shared theme created in the theme dir. Editing the shared copy would
     * be lost on the next app update, so it is promoted to the theme dir first.
     */
    fun ensureEditable(themeId: String): File? {
        val user = ThemeDirectory.userFile(themeId) ?: return null
        if (user.isFile) return user
        val shared = ThemeDirectory.sharedFile(themeId)?.takeIf { it.isFile } ?: return null
        return runCatching {
            user.parentFile?.mkdirs()
            shared.copyTo(user, overwrite = true)
            user
        }.onFailure { Timber.w(it, "Cannot promote theme '%s' to the user dir", themeId) }.getOrNull()
    }

    /** Reads the literal source of [key] from the `style:` block. */
    fun readEntry(
        file: File,
        key: String,
    ): Entry {
        val lines = readLines(file)
        return readEntry(lines, key)
    }

    /**
     * The file's lines, or an empty list when it cannot be read.
     *
     * Uses the same splitting as the writers ([ThemeTextFile]) so a line index
     * means the same thing on both sides.
     */
    fun readLines(file: File): List<String> = ThemeTextFile.read(file)?.lines.orEmpty()

    /**
     * [readEntry] over lines that were already read.
     *
     * The editor used to call the file version once per field, and each call
     * read the whole file: a 4000-line theme with thirty fields meant thirty
     * full reads while the screen was built. Callers that read many keys read
     * the file once and pass the lines here.
     */
    fun readEntry(
        lines: List<String>,
        key: String,
    ): Entry {
        val range = styleRange(lines) ?: return Entry(null, Source.ABSENT)
        val pattern = Regex("""^\s{2}${Regex.escape(key)}:\s*(.*)$""")
        for (i in range) {
            val match = pattern.find(lines[i]) ?: continue
            val raw = stripComment(match.groupValues[1])
            return if (raw.startsWith("*")) {
                Entry(raw.removePrefix("*").trim(), Source.ANCHOR)
            } else {
                Entry(raw.ifEmpty { null }, Source.LITERAL)
            }
        }
        return Entry(null, Source.ABSENT)
    }

    /**
     * Writes [value] (an already YAML-formatted scalar) for [key].
     *
     * An existing line keeps its indentation and trailing comment; a missing key
     * is appended to the end of the `style:` block.
     *
     * @return whether the file was written.
     */
    fun writeEntry(
        file: File,
        key: String,
        value: String,
    ): Boolean = writeEntryChecked(file, key, value).outcome == ThemeTextFile.WriteOutcome.WRITTEN

    /**
     * What a save did, plus the file's new contents when it happened.
     *
     * The text is handed back so a screen can keep editing without re-reading
     * the theme: it becomes the baseline for the next conflict check.
     */
    data class SaveResult(
        val outcome: ThemeTextFile.WriteOutcome,
        val text: String? = null,
    )

    /**
     * [writeEntry] with the reason it did not happen.
     *
     * @param expectedText the contents the caller last showed the user. When it
     *   is given and the file no longer holds it, nothing is written and the
     *   result is a conflict. Without it the check can never fail: this call
     *   reads the file itself, so it would always agree with what it just read
     *   — the "changed outside the app" case is precisely the one where the
     *   editor is holding an older copy.
     */
    fun writeEntryChecked(
        file: File,
        key: String,
        value: String,
        expectedText: String? = null,
    ): SaveResult {
        val document = ThemeTextFile.read(file) ?: return SaveResult(ThemeTextFile.WriteOutcome.FAILED)
        if (expectedText != null && document.text != expectedText) {
            Timber.w("Style file changed outside the app: %s", file.name)
            return SaveResult(ThemeTextFile.WriteOutcome.CONFLICT)
        }
        val lines = document.lines
        val range = styleRange(lines) ?: return SaveResult(ThemeTextFile.WriteOutcome.FAILED)

        var replaced = false
        for (i in range) {
            val match = ENTRY_INDENT.find(lines[i]) ?: continue
            if (match.groupValues[2] != key) continue
            val comment = commentOf(match.groupValues[4])
            lines[i] = "  $key: $value$comment"
            replaced = true
            break
        }

        if (!replaced) {
            var insertAt = range.last + 1
            while (insertAt > range.first && lines[insertAt - 1].isBlank()) insertAt--
            lines.add(insertAt, "  $key: $value")
        }

        val outcome = ThemeTextFile.writeChecked(file, document, lines)
        if (outcome != ThemeTextFile.WriteOutcome.WRITTEN) {
            Timber.w("Cannot write style '%s' to %s (%s)", key, file.name, outcome)
            return SaveResult(outcome)
        }
        return SaveResult(outcome, ThemeTextFile.render(document, lines))
    }

    /**
     * The entry a successful [writeEntry] leaves behind.
     *
     * The editor used to read the file back just to refresh one row, which is
     * another full pass over a several-thousand-line theme for something the
     * writer already knows: the line now reads `key: value`, literally.
     */
    fun writtenEntry(value: String): Entry = Entry(value, Source.LITERAL)

    /**
     * The scalar an `&anchor` definition carries, or null when it holds a block.
     *
     * An entry written as `key_height: *jpgd4` has no number on its own line —
     * the number lives wherever `&jpgd4` was defined, which in this theme is
     * three thousand lines of keyboard heights further up. An editor that put
     * the anchor's *name* in its input box would write `key_height: jpgd4` on
     * OK, turning a working theme into one that fails to parse, so the value has
     * to be looked up before it is offered for editing.
     *
     * Returns null rather than guessing when the definition is a mapping or a
     * sequence: those cannot be replaced by a single scalar, and the honest
     * answer is "this one cannot be edited here".
     */
    fun resolveAnchor(
        lines: List<String>,
        name: String,
    ): String? {
        val token = "&$name"
        for (line in lines) {
            val at = line.indexOf(token)
            if (at < 0) continue
            // `&jpgd4` must not match the definition of `&jpgd40`.
            val rest = line.substring(at + token.length)
            if (rest.isNotEmpty() && !rest[0].isWhitespace()) continue
            val scalar = stripComment(rest)
            if (scalar.isNotEmpty()) return stripQuotes(scalar)
        }
        return null
    }

    /** [resolveAnchor] over [file]; null when the file or the anchor is missing. */
    fun resolveAnchor(
        file: File,
        name: String,
    ): String? = resolveAnchor(readLines(file), name)

    private fun stripQuotes(value: String): String {
        if (value.length < 2) return value
        val first = value.first()
        if (first != '\'' && first != '"') return value
        if (value.last() != first) return value
        return value.substring(1, value.length - 1)
    }

    /** Index range of the lines inside the top-level `style:` block. */
    private fun styleRange(lines: List<String>): IntRange? {
        val start = lines.indexOfFirst { it.trimEnd() == "$STYLE_KEY:" || it.startsWith("$STYLE_KEY:") }
        if (start < 0) return null

        var end = lines.size
        for (i in start + 1 until lines.size) {
            val line = lines[i]
            if (line.isBlank()) continue
            // A non-indented, non-comment line closes the block.
            if (!line.startsWith(" ") && !line.startsWith("\t") && !line.startsWith("#")) {
                end = i
                break
            }
        }
        if (end <= start + 1) return null
        return (start + 1) until end
    }

    /**
     * Index of the `#` that starts a trailing comment, or -1 when there is none.
     *
     * A value can hold its own `#` (a `#RRGGBB` color), so only a hash preceded
     * by whitespace opens a comment.
     */
    private fun commentStart(raw: String): Int {
        for (i in 1 until raw.length) {
            if (raw[i] == '#' && raw[i - 1].isWhitespace()) return i
        }
        return -1
    }

    /** Drops a trailing `# comment` that is not part of the value. */
    internal fun stripComment(raw: String): String {
        val start = commentStart(raw)
        return (if (start >= 0) raw.substring(0, start) else raw).trim()
    }

    /**
     * Keeps the original trailing comment, including the whitespace before it.
     *
     * Themes are hand-written and often align comments with two spaces or a
     * tab; re-flowing that on every edit would produce noisy diffs.
     */
    internal fun commentOf(raw: String): String {
        val start = commentStart(raw)
        if (start < 0) return ""
        var from = start
        while (from > 0 && raw[from - 1].isWhitespace()) from--
        return raw.substring(from)
    }

    /** Formats a scalar for the `style:` block, quoting only when YAML needs it. */
    fun formatScalar(raw: String): String {
        val value = raw.trim()
        if (value.isEmpty()) return "\"\""
        val plain =
            value.toDoubleOrNull() != null ||
                value.equals("true", ignoreCase = true) ||
                value.equals("false", ignoreCase = true) ||
                value == "null" ||
                value == "~"
        if (plain) return value
        val needsQuote =
            value.firstOrNull()?.let { it.isWhitespace() || it in "#&*!|>'\"%@`{[," } == true ||
                value.lastOrNull()?.isWhitespace() == true ||
                value.contains(": ") ||
                value.contains(" #")
        return if (needsQuote) "'" + value.replace("'", "''") + "'" else value
    }
}
